"use client"

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type CSSProperties,
  type ReactNode,
  type RefObject,
} from "react"
import { Button } from "@/components/fiori/ui/button"
import { cn } from "@/lib/fiori/utils"
import { SapIcon } from "./sap-icon"
import "./list-report.css"

export type DynamicPageState = {
  expanded: boolean
  pinned: boolean
  phone: boolean
}

export type DynamicPageProps = Omit<ComponentProps<"div">, "title"> & {
  title: ReactNode
  header?: ReactNode
  summary?: ReactNode
  titleActions?: ReactNode | ((state: DynamicPageState) => ReactNode)
  expanded: boolean
  pinned: boolean
  onExpandedChange: (expanded: boolean) => void
  onPinnedChange: (pinned: boolean) => void
  onWidthChange?: (width: number) => void
  scrollContainerRef?: RefObject<HTMLElement | null>
  labels?: { expand?: string; collapse?: string; pin?: string; unpin?: string }
}

/** Resolve page scrolling; responsive tables do not add a second scrollbar. */
export function findPageScrollContainer(
  node: HTMLElement,
  explicit?: RefObject<HTMLElement | null>
) {
  return (
    explicit?.current ??
    node.closest<HTMLElement>("[data-fiori-scroll], .page-scroll")
  )
}

export function DynamicPage({
  title,
  header,
  summary,
  titleActions,
  expanded,
  pinned,
  onExpandedChange,
  onPinnedChange,
  onWidthChange,
  scrollContainerRef,
  labels,
  children,
  className,
  style,
  ref,
  ...props
}: DynamicPageProps) {
  const rootRef = useRef<HTMLDivElement>(null)
  const headerRef = useRef<HTMLElement>(null)
  const headerContentRef = useRef<HTMLDivElement>(null)
  const pendingScrollRef = useRef<number | null>(null)
  const suppressedScrollPositionRef = useRef<number | null>(null)
  const [geometry, setGeometry] = useState({
    width: 1024,
    headerHeight: 96,
    headerContentHeight: 0,
    rootRem: 16,
    viewportHeight: 720,
    canScroll: true,
  })
  const phone = geometry.width < 600
  // SAPUI5 1.151 DynamicPage: ceil(DynamicPageHeader height) - 1rem.
  // Keep this content measurement when collapsed; the title is not part of it.
  const snapThreshold = Math.max(
    Math.ceil(geometry.headerContentHeight) - geometry.rootRem,
    0
  )
  const shownExpanded = expanded && !phone && header != null
  const pinAvailable =
    shownExpanded &&
    geometry.canScroll &&
    geometry.headerHeight < geometry.viewportHeight * 0.6
  const effectivePinned = pinned && pinAvailable
  const state = { expanded: shownExpanded, pinned: effectivePinned, phone }
  const setRoot = useCallback(
    (node: HTMLDivElement | null) => {
      rootRef.current = node
      if (typeof ref === "function") ref(node)
      else if (ref) ref.current = node
    },
    [ref]
  )

  useEffect(() => {
    const root = rootRef.current,
      heading = headerRef.current
    if (!root || !heading) return
    const measure = () => {
      if (root.closest("[hidden]")) return
      const scroll = findPageScrollContainer(root, scrollContainerRef)
      const width = root.clientWidth
      const contentHeight =
        headerContentRef.current?.getBoundingClientRect().height ?? 0
      const rootRem =
        parseFloat(
          getComputedStyle(root.ownerDocument.documentElement).fontSize
        ) || 16
      setGeometry((previous) => ({
        width,
        headerHeight: heading.getBoundingClientRect().height,
        headerContentHeight:
          contentHeight > 0 ? contentHeight : previous.headerContentHeight,
        rootRem,
        viewportHeight: scroll?.clientHeight ?? window.innerHeight,
        canScroll: scroll
          ? scroll.scrollHeight > scroll.clientHeight + 1
          : document.documentElement.scrollHeight > window.innerHeight + 1,
      }))
      onWidthChange?.(
        root.querySelector<HTMLElement>(".order-worklist")?.clientWidth ?? width
      )
    }
    const observer = new ResizeObserver(measure)
    observer.observe(root)
    observer.observe(heading)
    if (headerContentRef.current) observer.observe(headerContentRef.current)
    const scroll = findPageScrollContainer(root, scrollContainerRef)
    if (scroll) observer.observe(scroll)
    measure()
    return () => observer.disconnect()
  }, [onWidthChange, scrollContainerRef])

  useLayoutEffect(() => {
    const requestedPosition = pendingScrollRef.current,
      root = rootRef.current
    if (requestedPosition == null || !root) return
    const scroll = findPageScrollContainer(root, scrollContainerRef)
    const before = scroll?.scrollTop ?? window.scrollY
    if (scroll) scroll.scrollTop = requestedPosition
    else window.scrollTo({ top: requestedPosition, behavior: "instant" })
    const after = scroll?.scrollTop ?? window.scrollY
    // Ignore only a scroll at the compensated position, never a later user scroll.
    suppressedScrollPositionRef.current = after !== before ? after : null
    pendingScrollRef.current = null
  }, [expanded, scrollContainerRef])

  useEffect(() => {
    const root = rootRef.current
    if (!root) return
    const scroll = findPageScrollContainer(root, scrollContainerRef)
    const target = scroll ?? window
    const onScroll = () => {
      const y = scroll?.scrollTop ?? window.scrollY
      const suppressedPosition = suppressedScrollPositionRef.current
      suppressedScrollPositionRef.current = null
      if (
        effectivePinned ||
        phone ||
        header == null ||
        root.closest("[hidden]") ||
        pendingScrollRef.current != null ||
        (suppressedPosition != null && y === suppressedPosition)
      )
        return
      if (y >= snapThreshold && expanded) {
        onExpandedChange(false)
      } else if (
        (y === 0 || y < snapThreshold) &&
        !expanded &&
        geometry.canScroll
      ) {
        onExpandedChange(true)
      }
    }
    target.addEventListener("scroll", onScroll, { passive: true })
    return () => target.removeEventListener("scroll", onScroll)
  }, [
    expanded,
    effectivePinned,
    phone,
    header,
    snapThreshold,
    geometry.canScroll,
    onExpandedChange,
    scrollContainerRef,
  ])

  useEffect(() => {
    if (pinned && !pinAvailable) onPinnedChange(false)
  }, [pinned, pinAvailable, onPinnedChange])

  const toggleHeader = () => {
    if (phone || header == null) return
    const root = rootRef.current
    if (root && geometry.canScroll) {
      const scroll = findPageScrollContainer(root, scrollContainerRef)
      const y = scroll?.scrollTop ?? window.scrollY
      // UI5's unpinned top collapse moves to ceil(H); collapsing a pinned header
      // releases it at T. Preserve the position for other manual toggles because
      // this layout keeps its sticky header in normal flow rather than moving it.
      pendingScrollRef.current = shownExpanded
        ? effectivePinned
          ? snapThreshold
          : Math.max(y, Math.ceil(geometry.headerContentHeight))
        : y
    }
    onExpandedChange(!shownExpanded)
    if (shownExpanded) onPinnedChange(false)
  }
  const expandLabel = shownExpanded
    ? (labels?.collapse ?? "收起筛选栏")
    : (labels?.expand ?? "展开筛选栏")
  const pinLabel = pinned
    ? (labels?.unpin ?? "取消固定页头")
    : (labels?.pin ?? "固定页头")

  return (
    <div
      {...props}
      ref={setRoot}
      className={cn("list-report", className)}
      data-header-expanded={shownExpanded}
      data-header-pinned={effectivePinned}
      data-header-snap-threshold={snapThreshold}
      style={
        {
          "--list-header-height": `${geometry.headerHeight}px`,
          ...style,
        } as CSSProperties
      }
    >
      <header className="list-page-header" ref={headerRef}>
        <div
          className="page-title-area"
          data-can-snap={!phone && header != null}
          onClick={(event) => {
            if (
              !(event.target as HTMLElement).closest(
                "button,a,input,select,[role=button]"
              )
            )
              toggleHeader()
          }}
        >
          <div className="page-title-row">
            <h1>{title}</h1>
            {typeof titleActions === "function"
              ? titleActions(state)
              : titleActions}
          </div>
          {!shownExpanded && summary != null && (
            <p className="collapsed-summary">{summary}</p>
          )}
        </div>
        <div ref={headerContentRef} hidden={!shownExpanded}>
          {header}
        </div>
        {!phone && header != null && (
          <div className="header-features">
            <Button
              variant="outline"
              size="icon-xs"
              aria-label={expandLabel}
              aria-expanded={shownExpanded}
              title={expandLabel}
              onClick={toggleHeader}
            >
              <SapIcon
                name={shownExpanded ? "slim-arrow-up" : "slim-arrow-down"}
              />
            </Button>
            {pinAvailable && (
              <Button
                variant="outline"
                size="icon-xs"
                aria-label={pinLabel}
                aria-pressed={pinned}
                title={pinLabel}
                onClick={() => onPinnedChange(!pinned)}
              >
                <SapIcon name={pinned ? "pushpin-on" : "pushpin-off"} />
              </Button>
            )}
          </div>
        )}
      </header>
      {children}
    </div>
  )
}

/* Shared Fiori List Report layout, adapted from the verified SAPUI5 1.151.0 / Morning Horizon prototype. */
[data-fiori-root] .list-report {
  min-height: 100%;
  background: var(--background);
  --list-toolbar-height: 48px;
  overflow-anchor: none;
  container-type: inline-size;
}
[data-fiori-root] .list-page-header {
  position: sticky;
  top: 0;
  z-index: 5;
  background: var(--card);
  box-shadow: var(--sapContent_HeaderShadow);
}
[data-fiori-root] .page-title-area {
  padding: 12px var(--page-gutter, 32px) 16px;
}
[data-fiori-root] .page-title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 32px;
}
[data-fiori-root] .page-title-row h1 {
  margin: 0;
  min-width: 0;
  font-size: 24px;
  font-weight: 700;
  line-height: 32px;
}
[data-fiori-root] .page-title-row .variant-trigger {
  font-size: 24px;
  font-weight: 700;
  padding: 0;
  height: auto;
  min-height: 32px;
  border-radius: 0;
  gap: 8px;
}
[data-fiori-root] .view-menu {
  min-width: 240px;
}
[data-fiori-root] .view-menu [data-slot="dropdown-menu-item"] {
  justify-content: space-between;
}
[data-fiori-root] .menu-section-label {
  display: block;
  color: var(--muted-foreground);
  font-size: 12px;
  padding: 8px 10px;
}
[data-fiori-root] .collapsed-summary {
  color: var(--muted-foreground);
  font-size: 14px;
  line-height: 20px;
  margin: 4px 0 0;
}
[data-fiori-root] .filter-bar {
  padding: 0 var(--page-gutter, 32px) 24px;
}
[data-fiori-root] [data-slot="field-group"].filter-grid {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 12px 16px;
  align-items: flex-end;
}
[data-fiori-root] .filter-grid [data-slot="field"] {
  width: 208px;
  flex: 0 0 208px;
  gap: 4px;
  min-height: 52px;
  justify-content: flex-end;
}
[data-fiori-root] .filter-grid .basic-search {
  min-height: 32px;
}
[data-fiori-root] .filter-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex: 1;
  min-height: 32px;
}
[data-fiori-root] .flex-spacer {
  flex: 1;
  min-width: 0;
}
[data-fiori-root] .header-features {
  position: absolute;
  left: 50%;
  bottom: -12px;
  transform: translateX(-50%);
  display: flex;
  gap: 8px;
}
[data-fiori-root] .header-features [data-slot="button"] {
  width: 24px;
  height: 24px;
  min-height: 24px;
  padding: 0;
  border-radius: 6px;
  background: var(--card);
  box-shadow: var(--sapContent_Shadow0);
}
[data-fiori-root] .header-features [aria-pressed="true"] {
  background: var(--primary);
  color: var(--primary-foreground);
}
[data-fiori-root] .list-content {
  padding: 24px var(--page-gutter, 32px) 32px;
}
[data-fiori-root] .order-worklist {
  background: var(--card);
}
[data-fiori-root] .table-toolbar {
  position: sticky;
  top: var(--list-header-height, 0px);
  z-index: 4;
  display: flex;
  align-items: center;
  gap: 8px;
  height: var(--list-toolbar-height, 48px);
  padding: 0 16px;
  background: var(--card);
  border-bottom: 1px solid var(--border);
}
[data-fiori-root] .table-toolbar h2 {
  font-size: 18px;
  font-weight: 700;
  line-height: 24px;
  white-space: nowrap;
  margin: 0;
}
[data-fiori-root] .toolbar-separator {
  height: 24px;
  align-self: center;
  margin: 0 4px;
}
[data-fiori-root] .responsive-table > [data-slot="table-container"] {
  overflow: visible;
}
[data-fiori-root] .orders-table {
  width: 100%;
  table-layout: auto;
}
[data-fiori-root] .orders-table [data-slot="table-head"] {
  position: sticky;
  top: calc(var(--list-header-height) + var(--list-toolbar-height));
  z-index: 3;
  height: 32px;
  background: var(--sapList_HeaderBackground);
  color: var(--sapList_HeaderTextColor);
  font-weight: 400;
  padding: 6px 12px;
  font-size: 14px;
  white-space: normal;
  box-shadow: inset 0 -1px var(--border);
}
[data-fiori-root] .orders-table [data-slot="table-cell"] {
  padding: 8px 12px;
  height: 56px;
  vertical-align: middle;
  white-space: normal;
  overflow-wrap: anywhere;
}
[data-fiori-root] .orders-table .checkbox-column {
  width: 48px;
  padding-left: 16px;
  padding-right: 8px;
}
[data-fiori-root] .orders-table .navigation-column {
  width: 40px;
  padding-left: 0;
  padding-right: 8px;
}
[data-fiori-root] .orders-table .col-id {
  min-width: 116px;
}
[data-fiori-root] .orders-table .col-customer {
  min-width: 180px;
}
[data-fiori-root] .orders-table .col-status {
  min-width: 88px;
}
[data-fiori-root] .orders-table .numeric-column {
  text-align: right;
  min-width: 124px;
}
[data-fiori-root] .orders-table .col-delivery {
  min-width: 124px;
}
[data-fiori-root] .orders-table .col-salesOrg {
  min-width: 120px;
}
[data-fiori-root] .orders-table .col-owner {
  min-width: 64px;
}
[data-fiori-root] .column-label {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
[data-fiori-root] .column-label svg {
  width: 12px;
  height: 12px;
}
[data-fiori-root] .order-row,
[data-fiori-root] .popin-row {
  cursor: pointer;
}
[data-fiori-root] .order-row {
  outline-offset: -2px;
}
[data-fiori-root] .orders-table [data-grid-key]:focus-visible {
  outline: 2px solid var(--ring);
}
[data-fiori-root] .order-row.has-popin {
  border-bottom: 0;
}
[data-fiori-root] .orders-table .has-popin .checkbox-column {
  vertical-align: top;
  padding-top: 20px;
}
[data-fiori-root] .orders-table .has-popin .navigation-column {
  vertical-align: top;
  padding-top: 12px;
}
[data-fiori-root] .object-identifier {
  display: flex;
  flex-direction: column;
  gap: 2px;
  align-items: flex-start;
}
[data-fiori-root] .object-identifier > strong {
  font-weight: 700;
}
[data-fiori-root] .object-identifier > span:last-child {
  font-size: 14px;
  color: var(--muted-foreground);
}
[data-fiori-root] .object-identifier .customer-name {
  color: var(--foreground);
  font-size: 14px;
  font-weight: 400;
}
[data-fiori-root] .fiori-link {
  color: var(--fiori-link, var(--primary));
  font-weight: 600;
  cursor: pointer;
  background: transparent;
  border: none;
  padding: 0;
  text-align: left;
}
[data-fiori-root] .fiori-link:hover {
  text-decoration: underline;
}
[data-fiori-root] .fiori-link:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
  border-radius: 2px;
}
[data-fiori-root] .object-number {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: baseline;
  gap: 4px;
  font-variant-numeric: tabular-nums;
}
[data-fiori-root] .object-number strong {
  font-weight: 400;
  white-space: nowrap;
}
[data-fiori-root] .object-number > span {
  color: var(--muted-foreground);
  font-size: 14px;
}
[data-fiori-root] .orders-table .popin-row [data-slot="table-cell"] {
  height: auto;
  padding-top: 0;
  padding-bottom: 12px;
}
[data-fiori-root] .popin-fields {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 24px;
  margin: 0;
}
[data-fiori-root] .popin-fields > div {
  min-width: 208px;
}
[data-fiori-root] .popin-fields dt {
  color: var(--muted-foreground);
  font-size: 14px;
  line-height: 20px;
  margin-bottom: 2px;
}
[data-fiori-root] .popin-fields dd {
  margin: 0;
  line-height: 20px;
}
[data-fiori-root] .popin-fields .object-number {
  justify-content: flex-start;
}
[data-fiori-root] .orders-table .table-no-data {
  height: 80px;
  color: var(--muted-foreground);
  text-align: center;
}
[data-fiori-root] .load-sentinel {
  height: 1px;
}
[data-fiori-root] .table-settings-dialog[data-slot="dialog-content"] {
  width: min(560px, calc(100vw - 32px));
  max-width: min(560px, calc(100vw - 32px));
}
[data-fiori-root] .table-settings-dialog > [data-slot="tabs"] {
  gap: 0;
}
[data-fiori-root] .table-settings-dialog [data-slot="tabs-list"] {
  width: 100%;
  justify-content: flex-start;
  padding: 0 24px;
  gap: 24px;
  border-bottom: 1px solid var(--border);
  height: 48px;
}
[data-fiori-root] .table-settings-dialog [data-slot="tabs-trigger"] {
  min-height: 48px;
  font-size: 14px;
}
[data-fiori-root] .column-options {
  display: flex;
  flex-direction: column;
  max-height: 55vh;
  overflow-y: auto;
}
[data-fiori-root] .column-option {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 24px;
  min-height: 44px;
  border-bottom: 1px solid var(--border);
}
[data-fiori-root] .column-option label {
  cursor: pointer;
}
[data-fiori-root] .sort-fields {
  padding: 24px;
}
[data-fiori-root][data-fiori-density="cozy"] .list-report,
[data-fiori-root][data-fiori-density="cozy"] .list-report {
  --list-toolbar-height: 56px;
}
[data-fiori-root][data-fiori-density="cozy"] .orders-table [data-slot="table-cell"],
[data-fiori-root][data-fiori-density="cozy"]
  .orders-table
  [data-slot="table-cell"] {
  height: 64px;
  padding-top: 12px;
  padding-bottom: 12px;
}
[data-fiori-root][data-fiori-density="cozy"] .orders-table .popin-row [data-slot="table-cell"],
[data-fiori-root][data-fiori-density="cozy"]
  .orders-table
  .popin-row
  [data-slot="table-cell"] {
  height: auto;
  padding-top: 0;
}
[data-fiori-root][data-fiori-density="cozy"] .orders-table [data-slot="table-head"],
[data-fiori-root][data-fiori-density="cozy"]
  .orders-table
  [data-slot="table-head"] {
  height: 44px;
}
[data-fiori-root][data-fiori-density="cozy"] .orders-table .has-popin .checkbox-column,
[data-fiori-root][data-fiori-density="cozy"]
  .orders-table
  .has-popin
  .checkbox-column {
  padding-top: 24px;
}
[data-fiori-root][data-fiori-density="cozy"] .orders-table .has-popin .navigation-column,
[data-fiori-root][data-fiori-density="cozy"]
  .orders-table
  .has-popin
  .navigation-column {
  padding-top: 16px;
}
@container (max-width: 700px) {
  [data-fiori-root] .table-toolbar {
    padding: 0 12px;
    gap: 4px;
  }
  [data-fiori-root] .table-toolbar h2 {
    font-size: 16px;
  }
}

@media (max-width: 599px) {
  [data-fiori-root] .table-settings-dialog[data-slot="dialog-content"] {
    inset: 0;
    --tw-translate-x: 0px;
    --tw-translate-y: 0px;
    transform: none;
    width: 100%;
    max-width: none;
    height: 100dvh;
    max-height: 100dvh;
    border-radius: 0;
  }
  [data-fiori-root] .table-settings-dialog > [data-slot="tabs"] {
    flex: 1;
    min-height: 0;
  }
  [data-fiori-root] .table-settings-dialog .column-options {
    max-height: none;
  }
  [data-fiori-root] .table-settings-dialog [data-slot="tabs-content"] {
    min-height: 0;
    overflow: auto;
  }
  [data-fiori-root] .page-title-area {
    padding: 12px 16px;
  }
  [data-fiori-root] .page-title-row {
    gap: 8px;
  }
  [data-fiori-root] .page-title-row .variant-trigger {
    font-size: 20px;
  }
  [data-fiori-root] .collapsed-summary {
    font-size: 14px;
  }
  [data-fiori-root] .list-content {
    padding: 16px 0 24px;
  }
  [data-fiori-root] .orders-table .checkbox-column {
    width: 40px;
    padding-left: 12px;
    padding-right: 4px;
  }
  [data-fiori-root] .orders-table .navigation-column {
    width: 32px;
    padding-right: 4px;
  }
  [data-fiori-root] .orders-table [data-slot="table-head"],
[data-fiori-root] .orders-table [data-slot="table-cell"] {
    padding-left: 8px;
    padding-right: 8px;
  }
  [data-fiori-root] .orders-table .col-id {
    min-width: 104px;
  }
  [data-fiori-root] .orders-table .numeric-column {
    min-width: 112px;
  }
  [data-fiori-root] .object-number {
    flex-direction: column;
    align-items: flex-end;
    gap: 0;
  }
  [data-fiori-root] .popin-fields {
    flex-direction: column;
    gap: 12px;
  }
}

[data-fiori-root] .page-title-area[data-can-snap="true"] {
  cursor: pointer;
}
[data-fiori-root] .order-row[data-navigable="false"] {
